// regra — /arquivos é a lista da API; nunca iterar 1..N (scripts/fopa/pncp.py:318-320, RN-07)
// regra — 429/5xx/rede: esperar 30 s e repetir UMA vez (scripts/fopa/pncp.py:62-70, ESPERA_429); esgotado → falha_rede
// regra — só statusAtivo, em ordem de sequencialDocumento (scripts/28_baixar_licitacao.py:499-513)
const r = $input.first().json || {};
const tentativa = $runIndex + 1;
const status = r.statusCode ?? null;
let falha = null;
let transitoria = false;
if (r.error) {
  falha = 'PNCP /arquivos sem resposta (rede/timeout): ' + String(r.error.message || r.error.description || JSON.stringify(r.error)).slice(0, 200);
  transitoria = true;
} else if (status !== 200 && status !== 204) {
  falha = `PNCP /arquivos respondeu HTTP ${status}`;
  transitoria = status === 429 || status >= 500;
}
let lista = [];
if (!falha && status === 200) {
  lista = r.body;
  if (typeof lista === 'string') {
    try { lista = lista.trim() ? JSON.parse(lista) : []; }
    catch (e) { falha = 'PNCP /arquivos devolveu um corpo que não é JSON'; lista = []; }
  }
  if (!Array.isArray(lista)) lista = lista ? [lista] : [];
}
const docs = lista
  .filter((a) => a && a.statusAtivo)
  .sort((a, b) => (a.sequencialDocumento || 0) - (b.sequencialDocumento || 0))
  .map((a) => ({ url: a.url || a.uri, sequencialDocumento: a.sequencialDocumento,
                 tipoDocumentoNome: a.tipoDocumentoNome, titulo: a.titulo, statusAtivo: a.statusAtivo }));
return [{ json: {
  tentativa, http_status: status, falha, motivo: falha,
  repetir: !!falha && transitoria && tentativa < 2,
  total: lista.length, ativos: docs.length, docs,
} }];

return [{ json: { ok: true, continuar: false, estado: 'sem_pdf_legivel',
  controle: $('Chamado pelo W20').first().json.controle,
  motivo: 'nenhum arquivo ativo no PNCP' } }];

// regra — laço dos jobs longos: Wait 15 s → GET /jobs/{id} enquanto `queued` OU `running`
// (api/rotas_jobs.py:13-16; api/jobs.py:18-20 — sucesso é `done`, não `ok`), máx. 60 voltas (plano §5 W21 passo 6).
// Worker sem resposta numa volta (reinício) não mata o laço: conta a volta e pergunta de novo.
const MAX = 60;
const r = $input.first().json || {};
const volta = $runIndex + 1;
const jobId = $('POST /jobs/baixar').first().json.body.job_id;
const b = (r.body && typeof r.body === 'object') ? r.body : {};
let status;
if (r.error) status = 'sem_resposta';
else if (r.statusCode !== 200) status = 'http_' + r.statusCode;
else status = String(b.status || 'desconhecido');
const ativo = status === 'queued' || status === 'running' || status === 'sem_resposta';
let motivo = null;
if (status === 'error') {
  const e = b.erro || {};
  motivo = `job ${jobId} falhou: ${e.tipo || 'erro'}: ${String(e.mensagem || '').slice(0, 300)}`;
} else if (ativo && volta >= MAX) {
  motivo = `job ${jobId} não terminou em ${MAX} voltas de 15 s (último status: ${status})`;
} else if (!ativo && status !== 'done') {
  motivo = `GET /jobs/${jobId} respondeu ${status}`;
}
return [{ json: {
  job_id: jobId, volta, status,
  continuar_esperando: ativo && volta < MAX,
  concluido: status === 'done',
  result: status === 'done' ? (b.result || {}) : null,
  progresso: b.progresso ?? null,
  motivo,
} }];

// regra — estado pelo resultado do download (scripts/28_baixar_licitacao.py:562-602): ≥1 PDF bom → baixada_ok;
// só formato → formato_nao_suportado (não se retenta); falha de rede → falha_rede (o W10 retenta); senão sem_pdf_legivel.
// A regra é UMA: o worker a aplica em api/baixar.py `estado_sugerido`, a mesma do importador do acervo.
const res = $json.result || {};
const arquivos = res.arquivos || [];
const bons = arquivos.filter((a) => a.status === 'ok');
const estado = res.estado_sugerido || 'sem_pdf_legivel';
const n_paginas = bons.reduce((s, a) => s + (a.pag || 0), 0);
const recusados = res.recusados || [];
const falhas = res.falhas_download || [];
const motivo = {
  baixada_ok: `W21: ${bons.length} arquivo(s), ${n_paginas} página(s)`,
  formato_nao_suportado: `W21: só formato não suportado (${recusados.length} recusado(s))`,
  falha_rede: `W21: download falhou na rede (${falhas.length} arquivo(s))`,
  sem_pdf_legivel: 'W21: nenhum PDF legível baixado',
}[estado] || ('W21: ' + estado);
return [{ json: {
  estado, motivo, job_id: $json.job_id,
  n_arquivos: bons.length, n_paginas, n_ocr: bons.filter((a) => a.requer_ocr).length,
  arquivos: bons.map((a) => ({ id: a.id, nome: a.nome, pag: a.pag, requer_ocr: a.requer_ocr, bytes: a.bytes })),
  recusados, falhas_download: falhas, total_bytes: res.total_bytes || 0,
} }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const quando = (iso, temHora) => {
  if (!iso) return 'sem data';
  const d = new Date(iso);
  const tz = 'America/Sao_Paulo';
  return temHora === false
    ? d.toLocaleDateString('pt-BR', { timeZone: tz })
    : d.toLocaleString('pt-BR', { timeZone: tz, day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
};
const site = String($env.FOPA_SITE_PUBLIC_URL || '').replace(/\/+$/, '');
const n8nBase = String($env.WEBHOOK_URL || '').replace(/\/+$/, '');
const linkExecucao = `${n8nBase}/workflow/${$workflow.id}/executions/${$execution.id}`;
// regra — e-mail "carregada" (plano §2 Alertas; §5 W21 passo 9): o fluxo só ENFILEIRA, quem envia é o W50
const lic = $('Transição → baixando').first().json;
const r = $('Estado pelo resultado').first().json;
const sessao = quando(lic.fim_prazo, lic.fim_prazo_tem_hora);
const onde = `${lic.municipio || lic.orgao || lic.controle}/${lic.uf || '—'}`;
const assunto = `[FOPA] Carregada: ${onde} · sessão ${sessao}`;
const pncp = lic.link || `https://pncp.gov.br/app/editais/${lic.cnpj}/${lic.ano}/${lic.seq}`;
const lista = (xs, f) => xs.length ? '<ul>' + xs.map((x) => '<li>' + f(x) + '</li>').join('') + '</ul>' : '<p>nenhum</p>';
const corpo = [
  `<p><b>${esc(lic.orgao || '')}</b> — ${esc(onde)}</p>`,
  `<p>${esc(lic.modalidade || 'modalidade não informada')} · controle ${esc(lic.controle)} · sessão ${esc(sessao)}</p>`,
  `<p>${esc(lic.objeto || '')}</p>`,
  `<p>${r.n_arquivos} arquivo(s), ${r.n_paginas} página(s); OCR previsto em ${r.n_ocr} arquivo(s).</p>`,
  lista(r.arquivos, (a) => `${esc(a.nome)} — ${a.pag ?? '?'} p.${a.requer_ocr ? ' (OCR)' : ''}`),
  `<p>Recusados pela política de coleta:</p>` + lista(r.recusados, (x) => `${esc(x.arquivo)} — ${esc(x.motivo)}`),
  r.falhas_download.length ? `<p>Falhas de download:</p>` + lista(r.falhas_download, (x) => `${esc(x.arquivo)} — ${esc(x.erro)}`) : '',
  `<p><a href="${esc(site)}/licitacao/${esc(lic.slug)}">Abrir no site</a> · <a href="${esc(pncp)}">PNCP</a> · `
    + `<a href="${esc(linkExecucao)}">execução ${esc($execution.id)} no n8n</a></p>`,
].join('');
return [{ json: { controle: lic.controle, assunto, corpo_html: corpo } }];

const r = $('Estado pelo resultado').first().json;
return [{ json: { ok: true, continuar: true, estado: 'baixada_ok',
  controle: $('Chamado pelo W20').first().json.controle, motivo: r.motivo,
  arquivos: r.n_arquivos, paginas: r.n_paginas, ocr: r.n_ocr, recusados: r.recusados.length,
  email_id: $json.email_id ?? null, job_id: r.job_id } }];

// formato_nao_suportado e sem_pdf_legivel são desfecho (não se retentam); falha_rede é erro: o W20 registra a falha e o backoff
const r = $('Estado pelo resultado').first().json;
return [{ json: { ok: r.estado !== 'falha_rede', continuar: false, estado: r.estado,
  controle: $('Chamado pelo W20').first().json.controle, motivo: r.motivo,
  recusados: r.recusados.length, falhas_download: r.falhas_download.length, job_id: r.job_id } }];

// Falha vira MOTIVO escrito (fica em licitacao_eventos e no retorno para o W20), nunca silêncio.
// Aceita o item de qualquer ramo que falhou: HTTP com erro de rede, HTTP com status ruim, laço esgotado.
const j = $input.first().json || {};
let motivo = j.motivo || j.falha || null;
if (!motivo && j.error) {
  motivo = 'sem resposta (rede/timeout): ' + String(j.error.message || j.error.description || JSON.stringify(j.error)).slice(0, 240);
}
if (!motivo && j.statusCode) {
  const corpo = typeof j.body === 'string' ? j.body : JSON.stringify(j.body ?? '');
  motivo = `HTTP ${j.statusCode}: ${corpo.slice(0, 300)}`;
}
return [{ json: { motivo: 'W21: ' + (motivo || 'falha sem motivo declarado') } }];

return [{ json: { ok: false, continuar: false, estado: 'falha_rede',
  controle: $('Chamado pelo W20').first().json.controle,
  motivo: $('Motivo da falha').first().json.motivo } }];
